import type { Theme, Tokens } from "./tokens.ts";

export const generatedMarker =
  "/* Generated by packages/brand/scripts/generate.ts from the TypeScript tokens. Do not edit. */";

const kebab = (name: string) => name.replace(/[A-Z]/g, (letter) => `-${letter.toLowerCase()}`);

function declarations(prefix: string, values: Record<string, string>): string[] {
  return Object.entries(values).map(([name, value]) => `  --${prefix}-${kebab(name)}: ${value};`);
}

function themeDeclarations(scheme: "light" | "dark", theme: Theme): string[] {
  return [
    `  color-scheme: ${scheme};`,
    ...declarations("color", { ...theme.colors }),
    ...declarations("shadow", theme.shadow),
  ];
}

const block = (selector: string, lines: string[], indent = "") =>
  [`${indent}${selector} {`, ...lines.map((line) => `${indent}${line}`), `${indent}}`].join("\n");

export function tokensCss(tokens: Tokens, scope: string): string {
  const shared = [
    ...declarations("accent", tokens.accent),
    ...declarations("neutral", tokens.neutral),
    ...declarations("font", tokens.font),
    ...declarations("weight", tokens.weight),
    ...declarations("text", tokens.text),
    ...declarations("leading", tokens.leading),
    ...declarations("tracking", tokens.tracking),
    ...declarations("space", tokens.space),
    ...declarations("radius", tokens.radius),
    ...declarations("border", tokens.border),
    ...declarations("z", tokens.z),
    ...declarations("duration", tokens.duration),
    ...declarations("ease", tokens.ease),
  ];
  const dark = themeDeclarations("dark", tokens.dark);
  return [
    generatedMarker,
    "",
    block(scope, [...shared, ...themeDeclarations("light", tokens.light)]),
    "",
    "@media (prefers-color-scheme: dark) {",
    block(`${scope}:not([data-theme="light"])`, dark, "  "),
    "}",
    "",
    block(`${scope}[data-theme="dark"]`, dark),
    "",
  ].join("\n");
}
